"use strict";
const $=id=>document.getElementById(id),t=OrionI18n.t;
const crosses=[['PP','pp'],['Pp','Pp'],['Pp','pp'],['PP','Pp'],['pp','PP'],['pp','Pp']];
const journeys=[[0,2,1],[4,3,1],[3,5,1],[2,0,1],[5,4,1],[1,3,2]];
let variant=OrionProgress.variant('inheritance'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget,stage=0,cells=['','','',''],solved=false,hintDepth=0,hintOpen=false,state='ready',saveFailed=false;
function challenge(v=variant,s=stage){return crosses[journeys[v][s]];}
function expected(i){const [a,b]=challenge();return [a[i%2],b[Math.floor(i/2)]].sort().join('');}
function setCell(i,value){if(solved||!Number.isInteger(i)||i<0||i>3||!['','PP','Pp','pp'].includes(value))return;cells[i]=value;state='ready';render();}
function cycle(i){const values=['','PP','Pp','pp'];setCell(i,values[(values.indexOf(cells[i])+1)%4]);}
function resetTrial(){cells=['','','',''];solved=false;hintDepth=0;hintOpen=false;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('inheritance')){variant=v;stage=0;resetTrial();}
function check(){if(solved)return;if(cells.some(c=>!c))state='incomplete';else if(cells.some((c,i)=>c!==expected(i)))state='wrong';else{solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('heritage');}render();if(solved&&stage<2)$('next').focus();}
function flower(c){const color=c==='pp'?'#fffbe7':'#c6a1ee';return `<svg viewBox="0 0 70 70" aria-hidden="true"><path d="M35 37v30M35 56q-24 -20 -22 -3q8 12 22 7" fill="#79bfa2" stroke="#82c4a5" stroke-width="3"/>${[0,72,144,216,288].map(a=>`<ellipse cx="35" cy="20" rx="10" ry="16" fill="${color}" stroke="#667a85" transform="rotate(${a} 35 33)"/>`).join('')}<circle cx="35" cy="33" r="7" fill="#efc87a"/></svg>`;}
function drawing(){const [a,b]=challenge();return `<div class="cross-grid"><span></span><strong>${a[0]} ↓</strong><strong>${a[1]} ↓</strong>${[0,1].map(row=>`<strong>${b[row]} →</strong>${[0,1].map(col=>{const i=row*2+col,c=cells[i];return `<button class="offspring" data-cell="${i}" ${solved?'disabled':''} aria-label="${t('Box '+(i+1)+', top '+a[col]+', side '+b[row]+', selected '+(c||'empty')+'. Tap to change.','第 '+(i+1)+' 格，上方 '+a[col]+'，左方 '+b[row]+'，已選 '+(c||'空白')+'。點選更改。')}">${c?flower(c):'<span class="unknown">?</span>'}<b>${c||'—'}</b><small>${c?t(c==='pp'?'White':'Purple',c==='pp'?'白花':'紫花'):t('Tap','點選')}</small></button>`;}).join('')}`).join('')}</div>`;}
function hints(){return[t('Each box takes one letter from above and one from its left. Keep uppercase P and lowercase p different.','每格取得上方和左方各一個字母。大寫 P 和小寫 p 並不相同。'),t('P with p makes Pp. In this simple flower model, PP and Pp are purple; pp is white.','P 和 p 組成 Pp。在這簡單花色模型中，PP 和 Pp 開紫花；pp 開白花。'),t('Read boxes across each row: '+[0,1,2,3].map(expected).join(', ')+'.','按每行由左至右填入：'+[0,1,2,3].map(expected).join('、')+'。')];}
function render(){const [a,b]=challenge(),complete=solved&&stage===2,p=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Pea Keeper’s Conservatory · Orion','豌豆守護者的溫室 · Orion');$('stageTitle').textContent=t(`Cross ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 組配對 · 題組 ${variant+1}`);$('sceneStatus').textContent=t(`Garden seals · ${p} / 3`,`花園封印 · ${p} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<p?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);$('diagram').innerHTML=drawing();$('goal').textContent=t('Top parent: '+a+' · Side parent: '+b,'上方親本：'+a+' · 左方親本：'+b);$('reading').textContent=t('Your boxes: '+cells.filter(c=>c&&c!=='pp').length+' purple · '+cells.filter(c=>c==='pp').length+' white · '+cells.filter(c=>!c).length+' empty','你的格子：'+cells.filter(c=>c&&c!=='pp').length+' 紫花 · '+cells.filter(c=>c==='pp').length+' 白花 · '+cells.filter(c=>!c).length+' 空白');$('reference').textContent=t('Tap a box to cycle: — → PP → Pp → pp → —.','點選格子輪流切換：— → PP → Pp → pp → —。');const messages={ready:['Combine the two edge letters in every box.','把兩邊的字母組合，填入每一格。'],incomplete:['Some boxes are empty. Fill all four possibilities.','還有空白格。請填好四種配對可能。'],wrong:['Some letter pairs do not match their edges. Try again.','有些字母組合與兩邊不符，再試試。'],success:['The possibilities match! Another garden seal opens.','配對可能正確！又一道花園封印打開。']};$('feedback').textContent=t(...messages[state]);$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintOpen));$('hints').hidden=!hintOpen;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('')+`<li class="close-clues"><button data-close>${t('Close clues','關閉提示')}</button></li>`;$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('heritage')?t('Heritage Sigil saved in your collection.','傳承符印已存入收藏。'):'';}
$('diagram').onclick=e=>{const b=e.target.closest('button[data-cell]');if(b){const i=Number(b.dataset.cell);cycle(i);$('diagram').querySelector('[data-cell="'+i+'"]').focus();}};
$('hints').onclick=e=>{if(e.target.closest('button[data-close]')){hintOpen=false;render();$('hint').focus();}};window.addEventListener('keydown',e=>{if(e.key==='Escape'&&hintOpen){hintOpen=false;render();$('hint').focus();}});$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);hintOpen=true;render();};
$('replay').onclick=()=>{const v=OrionProgress.nextVariant('inheritance',variant);observedVariant=OrionProgress.variant('inheritance');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('heritage');render();};function syncProgress(){const v=OrionProgress.variant('inheritance'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('heritage')&&!saveFailed)resetMission();else render();}window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
